"""More products for Preuet's catalogue (November 2026, second batch), defined like tools/new_products.py.

tools/fetch_prices.py build adds one of these only when it finds it at two supermarkets or more: a product with a price
at a single shop does not help to compare. Prices are never written here: they only come from the shops.
"""
N = lambda kcal, fat, sat, carb, sug, prot, salt, fib=None, basis="g": {  # noqa: E731
    "kcal": kcal, "fat": fat, "sat": sat, "carb": carb, "sug": sug, "prot": prot, "salt": salt, **({"fib": fib} if fib is not None else {}), "basis": basis}
FL = ["fresa", "chocolate", "vainilla", "limon", "platano", "melocoton", "frutas", "coco", "cacao", "canela", "miel", "macedonia", "avellana", "mango", "frambuesa", "arandanos", "cereza", "kiwi"]


def P(id, ca, es, cat, unit, ref, ref_ca, ref_es, q, must, avoid, size, nut=None, tags=(), allergens=(), traces=(), qca=None, start=True):
    """start: the shelf name must begin with the product itself ("Pizza 4 quesos" yes, "Bocaditos de pizza" no)."""
    return dict(id=id, ca=ca, es=es, cat=cat, unit=unit, ref=ref, ref_ca=ref_ca, ref_es=ref_es, q=q, must=must, avoid=avoid, size=size,
                nut=nut, tags=list(tags), allergens=list(allergens), traces=list(traces), qca=qca or ca.lower(), start=start)


